function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 50000) return 'arr needs 1 to 50000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each value is an integer from 0 to 10^9.';
  return null;
}

