function subarrayBitwiseORs(arr) {
  const all = new Set();
  let ending = new Set();

  for (const value of arr) {
    const next = new Set();
    next.add(value);
    for (const previous of ending) {
      next.add(previous | value);
    }
    for (const result of next) {
      all.add(result);
    }
    ending = next;
  }
  return all.size;
}

