function subarrayBitwiseORs(arr) {
  const seen = [];
  for (let start = 0; start < arr.length; start++) {
    let acc = 0;
    for (let end = start; end < arr.length; end++) {
      acc = acc | arr[end];
      if (!seen.includes(acc)) seen.push(acc);
    }
