    const style = Math.floor(rand() * 3);
    const arr = Array.from({ length: n }, () => {
      if (style === 0) return Math.floor(rand() * 1000000001);
      if (style === 1) return 1 << Math.floor(rand() * 30);
      return Math.floor(rand() * 64);
    });
    return [arr];
  }
  const n = 1 + Math.floor(rand() * 10);
  const style = Math.floor(rand() * 4);
  const arr = Array.from({ length: n }, () => {
    if (style === 0) return Math.floor(rand() * 8);
    if (style === 1) return 1 << Math.floor(rand() * 6);
    if (style === 2) return Math.floor(rand() * 3);
    return Math.floor(rand() * 1000000001);
  });
